/**
 * Generates src/theme.css from the Material 3 design system.
 *
 * Token values are not hand written: shape, type scale and elevation are read
 * from the token sources that ship inside @material/web, and the colour roles
 * are tonal palettes generated by @material/material-color-utilities from the
 * brand seed below.
 *
 * Run with: node scripts/make-theme.mjs
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { register } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

// @material/material-color-utilities 0.4.0 ships one extensionless relative
// import, which Node's ESM resolver rejects. Register a hook that retries the
// specifier with a .js extension so the script can run on plain Node.
register(
  `data:text/javascript,${encodeURIComponent(
    `export async function resolve(specifier, context, nextResolve) {
  try {
    return await nextResolve(specifier, context);
  } catch (error) {
    if (specifier.startsWith('.') || specifier.startsWith('/')) {
      return nextResolve(specifier + '.js', context);
    }
    throw error;
  }
}`
  )}`
);

const { argbFromHex, Hct, hexFromArgb, SchemeTonalSpot } = await import('@material/material-color-utilities');

const require = createRequire(import.meta.url);
const root = dirname(dirname(fileURLToPath(import.meta.url)));
const materialWeb = dirname(require.resolve('@material/web/package.json'));
const tokenDir = join(materialWeb, 'tokens', 'versions', 'v0_192');

/** Brand seed for the whole palette. */
const SEED = '#176b55';
/** Separate seed for the "success" role, which is not part of the core M3 roles. */
const SUCCESS_SEED = '#2e7d32';
/** Material colour spec revision used to resolve the palettes. */
const SPEC_VERSION = '2021';
/** The app layout follows the M3 4dp grid. */
const SPACING_PX = [0, 4, 8, 12, 16, 20, 24, 32, 40, 48, 56, 64];

const readTokenSource = (file) => readFileSync(join(tokenDir, file), 'utf8');

const kebab = (name) => name.replace(/([A-Z])/g, (m) => `-${m.toLowerCase()}`);

/** Parses the `'name': if($exclude-hardcoded-values, null, VALUE)` map shape. */
const parseLiteralMap = (scss, pattern) => {
  const out = {};
  for (const match of scss.matchAll(pattern)) out[match[1]] = match[2];
  return out;
};

const shape = parseLiteralMap(
  readTokenSource('_md-sys-shape.scss'),
  /'([a-z-]+)':\s*if\(\$exclude-hardcoded-values, null, ([0-9.]+px)\)/g
);

const typefaceSource = readTokenSource('_md-ref-typeface.scss');
const typefaceWeights = parseLiteralMap(
  typefaceSource,
  /'(weight-[a-z]+)':\s*if\(\$exclude-hardcoded-values, null, (\d+)\)/g
);
const typefaceFamilies = parseLiteralMap(
  typefaceSource,
  /'(brand|plain)':\s*if\(\$exclude-hardcoded-values, null, \((.+)\)\)/g
);

const typescaleSource = readTokenSource('_md-sys-typescale.scss');
const typeSizes = parseLiteralMap(
  typescaleSource,
  /'([a-z-]+)-size':\s*if\(\$exclude-hardcoded-values, null, ([0-9.]+rem)\)/g
);
const typeLineHeights = parseLiteralMap(
  typescaleSource,
  /'([a-z-]+)-line-height':\s*if\(\$exclude-hardcoded-values, null, ([0-9.]+rem)\)/g
);
const typeTracking = parseLiteralMap(
  typescaleSource,
  /'([a-z-]+)-tracking':\s*if\(\$exclude-hardcoded-values, null, (-?[0-9.]+rem)\)/g
);
const typeWeightNames = parseLiteralMap(
  typescaleSource,
  /'([a-z-]+)-weight':\s*map\.get\(\$deps, 'md-ref-typeface', '(weight-[a-z]+)'\)/g
);

const elevation = parseLiteralMap(
  readTokenSource('_md-sys-elevation.scss'),
  /'level(\d)':\s*if\(\$exclude-hardcoded-values, null, (\d+)\)/g
);

const typescaleRoles = [
  'display-large',
  'display-medium',
  'display-small',
  'headline-large',
  'headline-medium',
  'headline-small',
  'title-large',
  'title-medium',
  'title-small',
  'body-large',
  'body-medium',
  'body-small',
  'label-large',
  'label-medium',
  'label-small'
];

/** Colour roles, in the order Material Web declares them. */
const colorRoles = [
  'background',
  'onBackground',
  'primary',
  'onPrimary',
  'primaryContainer',
  'onPrimaryContainer',
  'primaryFixed',
  'primaryFixedDim',
  'onPrimaryFixed',
  'onPrimaryFixedVariant',
  'secondary',
  'onSecondary',
  'secondaryContainer',
  'onSecondaryContainer',
  'secondaryFixed',
  'secondaryFixedDim',
  'onSecondaryFixed',
  'onSecondaryFixedVariant',
  'tertiary',
  'onTertiary',
  'tertiaryContainer',
  'onTertiaryContainer',
  'tertiaryFixed',
  'tertiaryFixedDim',
  'onTertiaryFixed',
  'onTertiaryFixedVariant',
  'error',
  'onError',
  'errorContainer',
  'onErrorContainer',
  'surface',
  'onSurface',
  'surfaceVariant',
  'onSurfaceVariant',
  'surfaceDim',
  'surfaceBright',
  'surfaceContainerLowest',
  'surfaceContainerLow',
  'surfaceContainer',
  'surfaceContainerHigh',
  'surfaceContainerHighest',
  'surfaceTint',
  'inverseSurface',
  'inverseOnSurface',
  'inversePrimary',
  'outline',
  'outlineVariant',
  'shadow',
  'scrim'
];

const buildScheme = (isDark) =>
  new SchemeTonalSpot(Hct.fromInt(argbFromHex(SEED)), isDark, 0, SPEC_VERSION);
const buildSuccess = (isDark) =>
  new SchemeTonalSpot(Hct.fromInt(argbFromHex(SUCCESS_SEED)), isDark, 0, SPEC_VERSION);

const colorBlock = (scheme, success) => {
  const lines = [];
  for (const role of colorRoles) {
    const value = scheme[role];
    if (typeof value !== 'number') throw new Error(`Unknown colour role: ${role}`);
    lines.push(`  --md-sys-color-${kebab(role)}: ${hexFromArgb(value)};`);
  }
  lines.push(`  --md-sys-color-success: ${hexFromArgb(success.primary)};`);
  lines.push(`  --md-sys-color-on-success: ${hexFromArgb(success.onPrimary)};`);
  lines.push(`  --md-sys-color-success-container: ${hexFromArgb(success.primaryContainer)};`);
  lines.push(`  --md-sys-color-on-success-container: ${hexFromArgb(success.onPrimaryContainer)};`);
  return lines.join('\n');
};

const typeBlock = () => {
  const lines = [];
  for (const role of typescaleRoles) {
    const size = typeSizes[role];
    const lineHeight = typeLineHeights[role];
    const tracking = typeTracking[role];
    const weightName = typeWeightNames[role];
    if (!size || !lineHeight || !tracking || !weightName) {
      throw new Error(`Incomplete type scale entry: ${role}`);
    }
    const weight = typefaceWeights[weightName];
    if (!weight) throw new Error(`Unknown typeface weight: ${weightName}`);
    lines.push(`  --md-sys-typescale-${role}-size: ${size};`);
    lines.push(`  --md-sys-typescale-${role}-line-height: ${lineHeight};`);
    lines.push(`  --md-sys-typescale-${role}-tracking: ${tracking};`);
    lines.push(`  --md-sys-typescale-${role}-weight: ${weight};`);
    lines.push(`  --md-sys-typescale-${role}-font: ${typefaceFamilies.plain};`);
  }
  return lines.join('\n');
};

const shapeBlock = () =>
  Object.entries(shape)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([name, value]) => `  --md-sys-shape-${name}: ${value};`)
    .join('\n');

const elevationBlock = () =>
  Object.entries(elevation)
    .sort(([a], [b]) => Number(a) - Number(b))
    .map(([level, value]) => `  --md-sys-elevation-level${level}: ${value};`)
    .join('\n');

const spacingBlock = () =>
  SPACING_PX.map((px) => `  --space-${px / 4}: ${px / 16}rem;`).join('\n');

const css = `/* Generated by scripts/make-theme.mjs. Do not edit by hand. */

:root {
  color-scheme: light dark;

  /* Material 3 colour roles generated from the brand seed ${SEED}. */
${colorBlock(buildScheme(false), buildSuccess(false))}

  /* Material 3 type scale. */
${typeBlock()}

  /* Material 3 shape scale. */
${shapeBlock()}

  /* Material 3 elevation levels. */
${elevationBlock()}

  /* Layout spacing on the Material 4dp grid. */
${spacingBlock()}
}

@media (prefers-color-scheme: dark) {
  :root {
${colorBlock(buildScheme(true), buildSuccess(true))}
  }
}
`;

const target = join(root, 'src', 'theme.css');
writeFileSync(target, css, 'utf8');
console.log(`Wrote ${target}`);
